<?php
declare(strict_types=1);
namespace HardnessMcp\Tools\Finance;
use DateTimeImmutable;use HardnessMcp\Context\ExecutionContext;use HardnessMcp\Tools\Finance\Domain\FinanceSummaryRepositoryInterface;use HardnessMcp\Tools\Presentation\ToolResultPresenter;use HardnessMcp\Tools\ToolDefinition;use HardnessMcp\Tools\ToolExecutionResult;use HardnessMcp\Tools\ToolInterface;use InvalidArgumentException;
final class FinanceCashFlowTool implements ToolInterface {
    private FinanceSummaryRepositoryInterface $repository;private ToolResultPresenter $presenter;public function __construct(FinanceSummaryRepositoryInterface $repository,?ToolResultPresenter $presenter=null){$this->repository=$repository;$this->presenter=$presenter??new ToolResultPresenter();}
    public function getDefinition():ToolDefinition{return new ToolDefinition('hardness.finance.cash_flow_summary','Returns a combined management cash-flow forecast for accounts receivable and payable that are still open, grouped by week or month. It returns expected receipts, expected payments, and net cash flow. Both finance read permissions are required.',['type'=>'object','properties'=>['date_from'=>['type'=>'string','minLength'=>10,'maxLength'=>10],'date_to'=>['type'=>'string','minLength'=>10,'maxLength'=>10],'group_by'=>['type'=>'string','enum'=>['week','month']]],'required'=>['date_from','date_to','group_by'],'additionalProperties'=>false],['finance:receivables:read','finance:payables:read']);}
    /** @param array<string,mixed> $arguments */ public function execute(array $arguments,ExecutionContext $context):ToolExecutionResult{try{$from=$this->date((string)$arguments['date_from']);$to=$this->date((string)$arguments['date_to']);if($from>$to)throw new InvalidArgumentException('A data inicial não pode ser posterior à data final.');if((int)$from->diff($to)->format('%a')+1>366)throw new InvalidArgumentException('Relatórios interativos aceitam no máximo 12 meses.');$groupBy=(string)$arguments['group_by'];$rows=$this->rows($context->getCompanyId(),$from,$to,$groupBy);$summary=['receivable_open'=>'0.00','payable_open'=>'0.00','net_cash_flow'=>'0.00'];foreach($rows as $row){$summary['receivable_open']=$this->add($summary['receivable_open'],$row['receivable_open']);$summary['payable_open']=$this->add($summary['payable_open'],$row['payable_open']);$summary['net_cash_flow']=$this->add($summary['net_cash_flow'],$row['net_cash_flow']);}$result=['report'=>'cash_flow_summary','definition'=>'Previsão conjunta por vencimento, considerando exclusivamente o saldo em aberto de contas a receber e pagar.','period'=>['from'=>$from->format('Y-m-d'),'to'=>$to->format('Y-m-d')],'group_by'=>$groupBy,'summary'=>$summary,'rows'=>$rows];}catch(InvalidArgumentException $e){return $this->presenter->functionalError('cash_flow_summary_invalid_period',$e->getMessage(),'tools_call_cash_flow_summary_invalid_period');}catch(\Throwable $e){return $this->presenter->functionalError('cash_flow_summary_unavailable','Não foi possível consultar o fluxo de caixa agora. Tente novamente.','tools_call_cash_flow_summary_unavailable');}return $this->presenter->report($result,'Fluxo de caixa previsto',[['path'=>'summary.receivable_open','label'=>'A receber','format'=>'money'],['path'=>'summary.payable_open','label'=>'A pagar','format'=>'money'],['path'=>'summary.net_cash_flow','label'=>'Saldo líquido','format'=>'money']],'rows',[['path'=>$groupBy==='week'?'week_start':'month','label'=>$groupBy==='week'?'Semana de':'Mês','format'=>'date'],['path'=>'receivable_open','label'=>'A receber','format'=>'money'],['path'=>'payable_open','label'=>'A pagar','format'=>'money'],['path'=>'net_cash_flow','label'=>'Saldo líquido','format'=>'money']]);}
    /** @return array<int,array<string,string>> */ private function rows(int $companyId,DateTimeImmutable $from,DateTimeImmutable $to,string $groupBy):array{$dates=[];foreach(['receivable','payable'] as $kind){foreach($this->repository->grouped($kind,$companyId,$from->format('Y-m-d'),$to->format('Y-m-d'),'open',null,null,'day',367) as $row){$date=new DateTimeImmutable((string)$row['date']);$key=$groupBy==='week'?$date->modify('monday this week')->format('Y-m-d'):$date->format('Y-m-01');if(!isset($dates[$key]))$dates[$key]=['receivable_open'=>'0.00','payable_open'=>'0.00'];$field=$kind.'_open';$dates[$key][$field]=$this->add($dates[$key][$field],(string)$row['open_amount']);}}ksort($dates);$result=[];foreach($dates as $key=>$amounts)$result[]=[($groupBy==='week'?'week_start':'month')=>$key,'receivable_open'=>$amounts['receivable_open'],'payable_open'=>$amounts['payable_open'],'net_cash_flow'=>$this->subtract($amounts['receivable_open'],$amounts['payable_open'])];return $result;}
    private function add(string $left,string $right):string{return $this->money($this->cents($left)+$this->cents($right));}private function subtract(string $left,string $right):string{return $this->money($this->cents($left)-$this->cents($right));}private function cents(string $value):int{return (int)round((float)$value*100);}private function money(int $cents):string{return number_format($cents/100,2,'.','');}
    private function date(string $value):DateTimeImmutable{$date=DateTimeImmutable::createFromFormat('!Y-m-d',$value);$errors=DateTimeImmutable::getLastErrors();if($date===false||(is_array($errors)&&($errors['warning_count']>0||$errors['error_count']>0)))throw new InvalidArgumentException('Informe datas válidas no formato AAAA-MM-DD.');return $date;}
}
